// ————— Effort blocks: the ledger behind "Your tsumiki journey" —————
// HAND-MAINTAINED. Not generated by build-vite-app.py.
//
// The tracker row "Your tsumiki journey — effort blocks, structures, and a map
// of Japan" holds the decisions; docs/design/rework/12-journey.html is the
// approved look. This file is where blocks come from, and lib/journey.jsx draws
// them.
//
// ⚠️ A BLOCK IS EFFORT, NEVER GRADING. A wrong answer earns the same block as a
// right one. Nothing in here may read a score, a verdict or a correction — the
// checker's block keeps the sentence AS WRITTEN and nothing else from the check.
//
// ————— Where blocks come from —————
// Mostly NOT from the modules. Each source is read from a store that already
// records it, so the modules need no edits and a block's date is the real one:
//
//   kana lessons      the koban ledger's once-only "kana:<script>:<id>" payouts
//   grammar challenge the koban ledger's "challenge:<day>:<tier>" — one a day
//   vocabulary        "word completed" koban events — one block a day; and the
//                     words' own logs, via "check" — one review block a day
//   checker           checker-history-v1's _checks — the FIRST sentence of each
//                     week, at most one a week (decided)
//   showing up        recordVisit(), called by App on open — one a day, at most
//                     THREE a week (Lloyd, Oct 6 2026; was one a week)
//
// Grammar and kanji are the exception. "Finished" there depends on curriculum
// data only the module has (a point's kind, a lesson's characters), so those two
// modules call window.tsumikiBlocks.report() from an effect — idempotent, by id
// — and grammar adds a stage's keystones the same way.
//
// ⚠️ BLOCKS OUTLIVE THEIR SOURCE. A reset, a restore or the checker's own
// eviction never removes a block: this key is in no section of stats.js, and
// every id is deterministic, so re-reading a source never mints a block twice.
//
// ONE EXCEPTION, AND IT IS THE SENTENCE, NOT THE BLOCK (Lloyd, Oct 7 2026).
// Resetting the Checker deletes the learner's record of their own mistakes,
// and the sentence kept on a checker block is part of that record. So the
// reset clears it here too — clearCheckerSentences() — while the block stays,
// and its sheet says the sentence was deleted with the history. The merge in
// kobanMerge.js lets a cleared copy win, so the deletion reaches every device.
//
// ————— Backfill —————
// The first time grammar or kanji reports, everything it reports was finished
// BEFORE the tower existed, and no store recorded when. Those blocks carry
// `bf: true` and the screen says "Earned before your tower was built" rather
// than inventing a date. `seeded` records that a source has made its first
// report, and syncs, so a second device does not re-flag them.

import { storage } from "./storage.js";
import { LANDMARKS } from "./landmarks.js";

export const BLOCKS_KEY = "tsumiki-blocks-v1";
const KOBAN_KEY = "tsumiki-koban-ledger-v1";
const HISTORY_KEY = "tsumiki-checker-history-v1";
const WORDS_KEY = "tsumiki-known-words-v1";

export const LOGINS_PER_WEEK = 3;
const SOURCES = new Set(["hiragana", "katakana", "kanji", "grammar", "vocabulary", "checker", "login", "stage"]);
const ACTIONS = new Set(["lesson", "review", "check", "login", "stage"]);
const MODULE_SOURCES = new Set(["grammar", "kanji"]);

// ————— Tokyo calendar —————
// The app's day turns at midnight Tokyo time (the review challenge says so on
// Home), so a block's day and week do too. A week starts on Monday.
const JST = 9 * 3600e3;
export const tokyoDay = (ts) => new Date(ts + JST).toISOString().slice(0, 10);
export function weekOf(day) {
  const d = new Date(day + "T00:00:00Z");
  const dow = (d.getUTCDay() + 6) % 7;              // Monday = 0
  return new Date(d.getTime() - dow * 86400e3).toISOString().slice(0, 10);
}

// ————— The ledger —————
const parse = (s) => { try { return JSON.parse(s); } catch { return null; } };
const isObj = (x) => x && typeof x === "object" && !Array.isArray(x);
function validBlock(b) {
  return isObj(b) && typeof b.id === "string" && Number.isFinite(b.ts) && SOURCES.has(b.source) && ACTIONS.has(b.action);
}

export function shapeLedger(raw) {
  const v = isObj(raw) ? raw : {};
  return {
    v: 1,
    blocks: Array.isArray(v.blocks) ? v.blocks.filter(validBlock) : [],
    built: isObj(v.built) ? v.built : {},
    seeded: isObj(v.seeded) ? v.seeded : {},
  };
}

// Oldest first. Backfilled blocks go to the foundation: they are older than
// anything the tower has dated.
export function towerOrder(blocks) {
  return [...blocks].sort((a, b) => ((a.bf ? 0 : a.ts) - (b.bf ? 0 : b.ts)) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

export async function readBlocks() {
  let raw = null;
  try { const r = await storage.get(BLOCKS_KEY); raw = r ? parse(r.value) : null; } catch { raw = null; }
  const led = shapeLedger(raw);
  return { ...led, blocks: towerOrder(led.blocks) };
}

// One write at a time, as with koban: each mint is read-modify-write, and two
// in flight would each read the same ledger and the second would drop the first.
let queue = Promise.resolve();
function write(step) {
  const run = queue.then(async () => {
    let raw = null;
    try { const r = await storage.get(BLOCKS_KEY); raw = r ? parse(r.value) : null; } catch { raw = null; }
    const led = shapeLedger(raw);
    const out = step(led) || {};
    if (out.write) {
      try { await storage.set(BLOCKS_KEY, JSON.stringify(led)); } catch (e) { console.error("blocks save failed", e); }
    }
    announce(out.fresh);
    return out;
  });
  queue = run.catch(() => {});
  return run;
}

function clean(item, now) {
  const b = { id: String(item.id), ts: Number.isFinite(item.ts) ? item.ts : now, source: item.source, action: item.action };
  if (item.label) b.label = String(item.label).slice(0, 80);
  if (item.sentence) b.sentence = String(item.sentence).slice(0, 400);
  if (item.bf) b.bf = true;
  return validBlock(b) ? b : null;
}

// Add whichever of these ids the ledger does not already hold. Never updates an
// existing block: the first record of an effort is the record.
function addMissing(led, list, now, bf, fresh = []) {
  const have = new Set(led.blocks.map((b) => b.id));
  let added = 0;
  for (const it of list) {
    if (!it || !it.id || have.has(String(it.id))) continue;
    const b = clean(bf ? { ...it, bf: true } : it, now);
    if (!b) continue;
    led.blocks.push(b); have.add(b.id); added++; fresh.push(b);
  }
  return added;
}

// ————— Telling the learner (Lloyd, Oct 15 2026) —————
// "Let users know when they've received a block." Every block THIS device lays
// is announced on window as "tsumiki-blocks-laid"; lib/blockNotice.jsx shows
// it. Not announced: blocks arriving by sync (they never pass through here),
// back-filled ones (work from before the tower), and anything dated more than
// half a day ago — a restore or a first read of an old store is not news.
export const LAID_EVENT = "tsumiki-blocks-laid";
const NEWS_WINDOW = 12 * 3600e3;
function announce(fresh) {
  if (!Array.isArray(fresh) || typeof window === "undefined" || typeof CustomEvent === "undefined") return;
  const now = Date.now();
  const news = fresh.filter((b) => !b.bf && Math.abs(now - b.ts) < NEWS_WINDOW);
  if (news.length) try { window.dispatchEvent(new CustomEvent(LAID_EVENT, { detail: news })); } catch {}
}

// For the sources read centrally, which all carry their own dates.
export function ensureBlocks(items) {
  const list = Array.isArray(items) ? items : [];
  if (!list.length) return Promise.resolve({ added: 0 });
  return write((led) => {
    const fresh = [];
    const added = addMissing(led, list, Date.now(), false, fresh);
    return { added, fresh, write: added > 0 };
  });
}

// For a module reporting everything it now counts as finished (grammar, kanji).
// Called with the module's LOADED progress, every time it changes — including
// when nothing is finished yet, because that first report is what marks the
// source as seeded. Everything in a source's first report predates the tower,
// so it is back-filled (bf) rather than dated today.
export function reportBlocks(source, items) {
  if (!MODULE_SOURCES.has(source)) return Promise.resolve({ added: 0 });
  const list = Array.isArray(items) ? items : [];
  return write((led) => {
    const first = !led.seeded[source];
    const now = Date.now();
    const fresh = [];
    const added = addMissing(led, list, now, first, fresh);
    if (first) led.seeded[source] = now;
    return { added, fresh, write: added > 0 || first };
  });
}

// Showing up: one block a Tokyo day, and no more than LOGINS_PER_WEEK in a
// Tokyo week. Opening the app IS the act here — this is the one source that is
// about presence rather than work, which is why it is plain wood.
export function recordVisit(now = Date.now()) {
  const day = tokyoDay(now), week = weekOf(day);
  return write((led) => {
    const id = "login:" + day;
    if (led.blocks.some((b) => b.id === id)) return { added: false };
    const thisWeek = led.blocks.filter((b) => b.source === "login" && b.id.startsWith("login:") && weekOf(b.id.slice(6)) === week).length;
    if (thisWeek >= LOGINS_PER_WEEK) return { added: false };
    const b = { id, ts: now, source: "login", action: "login" };
    led.blocks.push(b);
    return { added: true, fresh: [b], write: true };
  });
}

// Called by stats.js when the Checker section is reset, before the reset is
// pushed to the account. Blocks keep their id, date and place in the tower.
export function clearCheckerSentences(now = Date.now()) {
  return write((led) => {
    let cleared = 0;
    for (const b of led.blocks) {
      if (b.source !== "checker" || b.cleared) continue;
      delete b.sentence;
      b.cleared = now;
      cleared++;
    }
    return { cleared, write: cleared > 0 };
  });
}

// `tok` is the token that paid for it (see nextBuild); it is stamped too, so
// the same kept week or milestone never pays for a second building.
export function markBuilt(structureId, now = Date.now(), tok = null) {
  return write((led) => {
    let changed = false;
    for (const k of [structureId, tok]) if (k && !led.built[k]) { led.built[k] = now; changed = true; }
    return changed ? { write: true } : {};
  });
}

// ————— Reading the sources —————
// Pure: (raw stored strings) -> block candidates. Exported for the tests.
export function candidatesFrom({ koban, history, words }) {
  const out = [];
  // Kana lessons and the grammar challenge, from the koban ledger.
  const k = parse(koban);
  const events = isObj(k) && Array.isArray(k.events) ? k.events : [];
  const vocabDays = new Map(), challengeDays = new Map();
  for (const e of events) {
    if (!isObj(e) || typeof e.id !== "string" || !Number.isFinite(e.ts) || e.ts <= 0) continue;
    const m = /^kana:(hiragana|katakana):(.+)$/.exec(e.id);
    if (m) { out.push({ id: `lesson:${m[1]}:${m[2]}`, ts: e.ts, source: m[1], action: "lesson" }); continue; }
    const c = /^challenge:(\d{4}-\d{2}-\d{2}):/.exec(e.id);
    if (c && !challengeDays.has(c[1])) challengeDays.set(c[1], e.ts);
    if (e.s === "vocabulary" && e.r === "word completed") {
      const d = tokyoDay(e.ts);
      if (!vocabDays.has(d)) vocabDays.set(d, e.ts);
    }
  }
  for (const [d, ts] of challengeDays) out.push({ id: `review:grammar:${d}`, ts, source: "grammar", action: "review" });
  for (const [d, ts] of vocabDays) out.push({ id: `lesson:vocabulary:${d}`, ts, source: "vocabulary", action: "lesson" });

  // Vocabulary reviews: a day with checked reviews in any word's log.
  const w = parse(words);
  if (isObj(w)) {
    const days = new Map();
    for (const [key, p] of Object.entries(w)) {
      if (key.startsWith("_") || !isObj(p) || !Array.isArray(p.log)) continue;
      for (const l of p.log) {
        if (!isObj(l) || l.via !== "check" || !Number.isFinite(l.t)) continue;
        const d = tokyoDay(l.t);
        if (!days.has(d) || days.get(d) > l.t) days.set(d, l.t);
      }
    }
    for (const [d, ts] of days) out.push({ id: `review:vocabulary:${d}`, ts, source: "vocabulary", action: "review" });
  }

  // The checker: the first sentence checked in each week, kept as written.
  // `d` is the only date a check carries (a UTC day), so the block is dated
  // noon that day. Checks are evicted after a few hundred; a block minted from
  // one is not.
  const h = parse(history);
  const checks = isObj(h) && Array.isArray(h._checks) ? h._checks : [];
  const firstOfWeek = new Map();
  for (const c of checks) {
    if (!isObj(c) || typeof c.d !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(c.d) || typeof c.text !== "string" || !c.text.trim()) continue;
    const wk = weekOf(c.d);
    const prev = firstOfWeek.get(wk);
    if (!prev || c.d < prev.d) firstOfWeek.set(wk, c);
  }
  for (const [wk, c] of firstOfWeek) {
    out.push({ id: `check:${wk}`, ts: Date.parse(c.d + "T03:00:00Z"), source: "checker", action: "check", sentence: c.text.trim() });
  }
  return out;
}

export async function reconcileBlocks() {
  const get = async (k) => { try { return (await storage.get(k))?.value ?? null; } catch { return null; } };
  const [koban, history, words] = await Promise.all([get(KOBAN_KEY), get(HISTORY_KEY), get(WORDS_KEY)]);
  return ensureBlocks(candidatesFrom({ koban, history, words }));
}

// Modules call this. It is a global, like window.storage, so the module source
// stays the same in the artifact build, where it is simply absent.
export function installBlocks() {
  if (typeof window !== "undefined" && !window.tsumikiBlocks) window.tsumikiBlocks = { report: reportBlocks };
}

// ————— Structures —————
// THE FIRST THREE (Session 39, Oct 6 2026) keep their own recipes and ids —
// learners have already built them, and `built` is keyed by these ids. Every
// other building is a landmark from lib/landmarks.js (Session 39.2's 182 sites;
// these three are its #76, #62 and #33). Thresholds are never shown anywhere —
// the screen announces a building only once it is earned, in the past tense,
// and never previews the next one. Slot letters in `grid` pick the learner's
// blocks by preference.
const FIRST = {
  torii: {
    kind: "first", n: 76, size: "S", jp: "鳥居", kana: "とりい", en: "torii",
    place: { jp: "厳島神社", kana: "いつくしまじんじゃ", en: "Itsukushima Shrine — Miyajima, Hiroshima", pref: "Hiroshima", x: 64.1, y: 245.7, label: "below" },
    earned: (c) => c.kana >= 15 && c.login >= 12,
    grid: ["BBBBBBBBBB", ".BBBBBBBB.", "..P....P..", ".BBBBBBBB.", "..P....P..", "..P....P..", "..P....P..", "..P....P..", ".LL....LL."],
    prefer: { B: ["kana"], P: ["kana"], L: ["login"] },
  },
  pagoda: {
    kind: "first", n: 62, size: "M", jp: "五重塔", kana: "ごじゅうのとう", en: "five-story pagoda",
    place: { jp: "法隆寺", kana: "ほうりゅうじ", en: "Hōryū-ji — Ikaruga, Nara", pref: "Nara", x: 123.0, y: 238.7 },
    earned: (c) => c.kanji >= 20,
    grid: [".....S.....", ".....S.....", "...RRRRR...", "....WWW....", "..RRRRRRR..", "....WWW....", "..RRRRRRR..", "...WWWWW...", ".RRRRRRRRR.", "...WWWWW...", "RRRRRRRRRRR", "..WWWWWWW..", ".LLLLLLLLL."],
    prefer: { S: ["stage"], R: ["kanji"], W: ["kanji", "review"], L: ["login"] },
  },
  castle: {
    kind: "first", n: 33, size: "L", jp: "天守", kana: "てんしゅ", en: "castle keep",
    place: { jp: "松本城", kana: "まつもとじょう", en: "Matsumoto Castle — Matsumoto, Nagano", pref: "Nagano", x: 161.5, y: 203.4 },
    earned: (c) => c.kanji >= 20 && c.vocabulary >= 15,
    grid: ["....S..S....", "...RRRRRR...", "....WWWW....", "..RRRRRRRR..", "...WWWWWW...", ".RRRRRRRRRR.", "..WWWWWWWW..", "..WWWWWWWW..", ".LLLLLLLLLL.", "LLLLLLLLLLLL"],
    prefer: { S: ["stage"], R: ["vocabulary"], W: ["kanji"], L: ["login"] },
  },
};
export const RECIPES = { ...FIRST, ...LANDMARKS };

// "a castle keep", "an old street" — for the announcement and the sheet.
export const withArticle = (en) => (/^[aeiou]/i.test(en) ? "an " : "a ") + en;

const isKana = (b) => b.source === "hiragana" || b.source === "katakana";
export function tally(blocks) {
  const c = { kana: 0, login: 0, kanji: 0, vocabulary: 0, grammar: 0 };
  for (const b of blocks) {
    if (isKana(b)) c.kana++;
    else if (b.source in c) c[b.source]++;
  }
  return c;
}

// ————— What earns a landmark (Lloyd, Oct 12–15 2026) —————
// Two ways, both effort, both past tense:
//
//   A KEPT WEEK — three days of showing up in a Tokyo week (the login cap), OR
//   a Goals path completed that week — earns one landmark, about one a week.
//   The first four are small, then small or middle-sized. A missed week simply
//   has none: nothing is taken away and nothing is owed.
//
//   A MILESTONE — every so many blocks of one kind, and every grammar stage
//   finished — earns one of the LARGE landmarks, so the big ones mark long
//   stretches of work.
//
// Which landmark a token gets is drawn from what is still unbuilt, seeded by
// the token, so every device holding the same ledger draws the same one. The
// draw happens when it is announced, and `built` records both the landmark and
// the token that paid for it, so a token is spent once.
//
// (The village of small buildings planned Oct 12 is cut — Lloyd, Oct 15: the
// landmark library is big enough to carry the weekly rhythm on its own.)
export const MILESTONES = [
  { key: "kana", every: 25, is: isKana },
  { key: "kanji", every: 25, is: (b) => b.source === "kanji" && b.action !== "review" },
  { key: "vocabulary", every: 20, is: (b) => b.source === "vocabulary" && b.action !== "review" },
  { key: "review", every: 25, is: (b) => b.action === "review" },
  { key: "checker", every: 13, is: (b) => b.source === "checker" },
  { key: "login", every: 40, is: (b) => b.source === "login" },
];
const SMALL_FIRST = 4;     // the first kept weeks bring small landmarks only

const when = (b) => (b.bf ? 0 : b.ts);
function fnv(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

// Goals paths completed, by Tokyo week, from the koban ledger's "path
// completed" payouts (Engagement.jsx: id "quest:<startedOn>:<tasks>:chain").
export function pathWeeksFrom(kobanRaw) {
  const k = parse(kobanRaw);
  const out = {};
  for (const e of isObj(k) && Array.isArray(k.events) ? k.events : []) {
    if (!isObj(e) || typeof e.id !== "string" || !Number.isFinite(e.ts) || !/^quest:.*:chain$/.test(e.id)) continue;
    const wk = weekOf(tokyoDay(e.ts));
    if (!(wk in out) || e.ts < out[wk]) out[wk] = e.ts;
  }
  return out;
}
export async function readPathWeeks() {
  try { const r = await storage.get(KOBAN_KEY); return pathWeeksFrom(r ? r.value : null); } catch { return {}; }
}

// Every token the learner has earned, oldest first. Pure; exported for tests.
export function earnedTokens(blocks, pathWeeks = {}) {
  const ordered = towerOrder(blocks);
  const out = [];
  // The first three: the moment the running tally first met the recipe.
  const c = { kana: 0, login: 0, kanji: 0, vocabulary: 0, grammar: 0 };
  const firstAt = {};
  // Milestones: every `every` blocks of a kind.
  const counts = Object.fromEntries(MILESTONES.map((m) => [m.key, 0]));
  const stages = new Map();
  const logins = new Map();
  for (const b of ordered) {
    if (isKana(b)) c.kana++; else if (b.source in c) c[b.source]++;
    for (const id of Object.keys(FIRST)) if (!(id in firstAt) && FIRST[id].earned(c)) firstAt[id] = when(b);
    for (const m of MILESTONES) {
      if (!m.is(b)) continue;
      counts[m.key]++;
      if (counts[m.key] % m.every === 0) out.push({ tok: `m:${m.key}:${counts[m.key]}`, ts: when(b), kind: "milestone" });
    }
    // A finished grammar stage: its keystones share "stage:<lesson>:".
    if (b.source === "stage") {
      const sk = b.id.replace(/:\d+$/, "");
      if (!stages.has(sk)) stages.set(sk, when(b));
    }
    if (b.source === "login" && /^login:\d{4}-\d{2}-\d{2}$/.test(b.id)) {
      const wk = weekOf(b.id.slice(6));
      const l = logins.get(wk) || [];
      l.push(when(b));
      logins.set(wk, l);
    }
  }
  for (const [id, ts] of Object.entries(firstAt)) out.push({ tok: id, ts, kind: "first" });
  for (const [sk, ts] of stages) out.push({ tok: `m:${sk}`, ts, kind: "milestone" });
  const weeks = new Map();
  for (const [wk, l] of logins) if (l.length >= LOGINS_PER_WEEK) weeks.set(wk, l.sort((a, b) => a - b)[LOGINS_PER_WEEK - 1]);
  for (const [wk, ts] of Object.entries(isObj(pathWeeks) ? pathWeeks : {})) {
    if (!Number.isFinite(ts)) continue;
    if (!weeks.has(wk) || ts < weeks.get(wk)) weeks.set(wk, ts);
  }
  for (const [wk, ts] of weeks) out.push({ tok: `w:${wk}`, ts, kind: "week" });
  const rank = { first: 0, milestone: 1, week: 2 };
  out.sort((a, b) => (a.ts - b.ts) || (rank[a.kind] - rank[b.kind]) || (a.tok < b.tok ? -1 : a.tok > b.tok ? 1 : 0));
  let wi = 0;
  for (const t of out) if (t.kind === "week") t.idx = wi++;
  return out;
}

// Size tiers tried in order; the first with anything left is drawn from.
const TIERS = { early: [["S"], ["M"], ["L"]], week: [["S", "M"], ["L"]], milestone: [["L"], ["M"], ["S"]] };
// The landmark a token draws, from those neither built nor already drawn.
export function drawFor(t, built = {}, held = new Set()) {
  if (t.kind === "first") return t.tok;
  const tiers = t.kind === "milestone" ? TIERS.milestone : t.idx < SMALL_FIRST ? TIERS.early : TIERS.week;
  const ids = Object.keys(LANDMARKS).sort();
  for (const sizes of tiers) {
    const pool = ids.filter((id) => !built[id] && !held.has(id) && sizes.includes(LANDMARKS[id].size));
    if (pool.length) return pool[fnv(t.tok) % pool.length];
  }
  return null;
}

export const slotCount = (id) => RECIPES[id].grid.join("").replace(/\./g, "").length;

// The one building to announce now, with the token it spends — or null. Past
// tense only: this is never asked "what is next?". A building is also never
// announced before the tower holds enough blocks to build it WHOLE — a torii
// with gaps in its beam reads as something taken away. A token whose draw is
// too big for the tower yet keeps its draw and waits; later tokens draw around it.
export function nextBuild(blocks, built = {}, pathWeeks = {}) {
  const held = new Set();
  for (const t of earnedTokens(blocks, pathWeeks)) {
    if (built[t.tok]) continue;
    const id = drawFor(t, built, held);
    if (!id || (t.kind === "first" && built[id])) continue;
    held.add(id);
    if (blocks.length >= slotCount(id)) return { id, tok: t.tok };
  }
  return null;
}
export function earnedUnbuilt(blocks, built = {}, pathWeeks = {}) {
  const n = nextBuild(blocks, built, pathWeeks);
  return n ? n.id : null;
}

const matches = (b, pref) => pref === "kana" ? isKana(b) : pref === "review" ? b.action === "review" : b.source === pref;

// Pick the learner's blocks for a building, oldest first, by slot preference,
// filled bottom-up so a build assembles from the ground.
export function assignForBuilding(id, blocks) {
  const r = RECIPES[id];
  const used = new Set(), slots = [];
  r.grid.forEach((line, y) => [...line].forEach((ch, x) => { if (ch !== ".") slots.push({ x, y, ch }); }));
  slots.sort((a, b) => b.y - a.y || a.x - b.x);
  const ordered = towerOrder(blocks);
  const take = (pred) => { const b = ordered.find((x) => !used.has(x.id) && pred(x)); if (b) used.add(b.id); return b || null; };
  for (const s of slots) {
    let b = null;
    for (const p of r.prefer[s.ch] || []) if ((b = take((x) => matches(x, p)))) break;
    s.b = b || take((x) => x.source !== "stage") || take(() => true);
  }
  return { slots: slots.filter((s) => s.b), cols: Math.max(...r.grid.map((l) => l.length)), rows: r.grid.length };
}
